def test_command_main_handles_interrupt_while_reporting_interrupt(runner, monkeypatch):
    @click.command()
    def cli():
        raise KeyboardInterrupt()

    original_echo = click.core.echo

    def echo(message=None, *args, **kwargs):
        if message is None:
            raise KeyboardInterrupt()

        return original_echo(message, *args, **kwargs)

    monkeypatch.setattr(click.core, "echo", echo)

    result = runner.invoke(cli)

    assert result.exit_code == 1
    assert isinstance(result.exception, SystemExit)
    assert result.exception.code == 1
    assert result.output == "Aborted!\n"


